<?php
 namespace QQWorld\Backend\Model; use QQWorld\Framework\App\Router\PathConfigInterface; use QQWorld\Store\Model\Store; class AdminPathConfig implements PathConfigInterface { protected $coreConfig; protected $backendConfig; protected $url; public function __construct( \QQWorld\Framework\App\Config\ScopeConfigInterface $coreConfig, \QQWorld\Backend\App\ConfigInterface $backendConfig, \QQWorld\Framework\UrlInterface $url ) { $this->coreConfig = $coreConfig; $this->backendConfig = $backendConfig; $this->url = $url; } public function getCurrentSecureUrl(\QQWorld\Framework\App\RequestInterface $request) { return $this->url->getBaseUrl('link', true) . ltrim($request->getPathInfo(), '/'); } public function shouldBeSecure($path) { return parse_url( (string)$this->coreConfig->getValue(Store::XML_PATH_UNSECURE_BASE_URL, 'default'), PHP_URL_SCHEME ) === 'https' || $this->backendConfig->isSetFlag(Store::XML_PATH_SECURE_IN_ADMINHTML) && parse_url( (string)$this->coreConfig->getValue(Store::XML_PATH_SECURE_BASE_URL, 'default'), PHP_URL_SCHEME ) === 'https'; } public function getDefaultPath() { return $this->backendConfig->getValue('web/default/admin'); } } 